import React from 'react';
import { Box, IconButton, Stack, Typography } from '@mui/material';

// component
import BaseCard from '../BaseCard';

// icons
import InstagramIcon from '@mui/icons-material/Instagram';
import { ArrowBack, ArrowForward } from '@mui/icons-material';

interface InstagramProps {

};

function Instagram(props: InstagramProps) {
    const [currentImageIdx, setCurrentImageIdx] = React.useState<number>(0);
    // const numOfImages= 3;

    const handleNext = () => {
        setCurrentImageIdx((prev) => (prev + 1) % 3);
    };

    const handlePrev = () => {
        setCurrentImageIdx((prev) => (prev - 1 + 3) % 3);
    };

    return (
        <BaseCard
            sx={{
                height: "100%",
                width: "99vw",
                flexDirection: "column",
                maxWidth: "sm",
                gap: 0
            }}
        >
            <Stack width="100%" px={2} py={1} direction="row" justifyContent="space-between" alignItems="center"  >
                <InstagramIcon />

                <Stack direction="row" gap={1} alignItems="center" >
                    <IconButton
                        onClick={handlePrev}
                    >
                        <ArrowBack />
                    </IconButton>
                    <IconButton
                        onClick={handleNext}
                    >
                        <ArrowForward />
                    </IconButton>
                </Stack>
            </Stack>

            <Stack flex={1} position="relative" overflow="hidden" height="100%" width="100%" direction="row" justifyContent="space-between" alignItems="center">
                {
                    Array(3).fill("").map((_, idx) => (
                        <img
                            src={`/static/psyborgs-git/ig/${idx}.jpg`}
                            style={{
                                height: "100%",
                                width: "100%",
                                objectFit: "cover",
                                transition: "transform 500ms ease-in-out",
                                position: "absolute",
                                left: 0,
                                top: 0,
                                transform: `translateX(${(idx - currentImageIdx) * 100}%)`
                            }}
                        />
                    ))
                }
            </Stack>

            <Typography
                onClick={() => window.open("https://www.instagram.com/jainamsha/", "_blank")}
                variant="body1"
                p={2}
                textAlign="center"
                children="@jainamsha"
            />

        </BaseCard>
    );

};

export default Instagram;
